#!/usr/bin/env python3
"""Read-only Git custody and fixed-tree lifecycle adversarial controls."""
import review_checks as r
from pathlib import Path
from unittest.mock import patch
import copy, hashlib, json, os, shutil, sys, types

r.EVENTS=r.read(r.WORK/'events.json')
HIST=r.WORK.parent/'repair-recheck-work-19bc99/cases/correct-postrun/trial'

def full_freeze():
 root=r.WORK/'cases/fresh-freeze';root.mkdir()
 p=r.read(r.FIX/'paired/protocol.json')
 p['freeze']={'status':'draft','protocol_sha256':None,'commit':None,'frozen_at':None,'filed_before_affected_data':False}
 r.write(root/'protocol.json',p)
 r.command('fresh-complete-protocol-freeze',[sys.executable,str(r.REPO/'tools/experiment_protocol.py'),'freeze',str(root/'protocol.json')])
 r.command('fresh-complete-frozen-validate',[sys.executable,str(r.REPO/'tools/experiment_protocol.py'),'validate',str(root/'protocol.json')])
 assert r.ep.protocol_hash(p)==r.read(root/'protocol.json')['freeze']['protocol_sha256']
 # A schema-complete one-arm protocol is a stronger control than old skeletal bytes.
 p['arms'].pop();p['protocol_id']='TEST-ONE-ARM-REJECT';r.write(root/'one-arm.json',p)
 r.command('complete-one-arm-schema-reject',[sys.executable,str(r.REPO/'tools/experiment_protocol.py'),'validate',str(root/'one-arm.json')],expected=1)
 # Also run the old exact skeletal TEST-F11 document, historically unqualified.
 shutil.copy2(HIST/'protocol.json',root/'historical-skeletal.json')
 r.command('historical-skeletal-protocol-reject',[sys.executable,str(r.REPO/'tools/experiment_protocol.py'),'validate',str(root/'historical-skeletal.json')],expected=1)
 return {'protocol_hash':r.read(root/'protocol.json')['freeze']['protocol_sha256'],'file_sha256':r.sha(root/'protocol.json'),'test_only':True,'production_protocol_authored':False}

def lifecycle():
 answers={}
 for label in ['positive-envelope','corrupt-archive','missing-member','wrong-independent-pins','zero-start-envelope']:
  root=r.WORK/'cases/lifecycle'/label;root.mkdir(parents=True)
  source=root/'fixed-input';shutil.copytree(HIST,source)
  record=r.read(source/'controller-receipt.json')
  (source/'protocol.json').unlink();r.c.write(source/'protocol.json',{'protocol_id':'EXP-FIXTURE'})
  expected=copy.deepcopy(record['plan']);invocation=r.read(source/'config.json')
  if label=='wrong-independent-pins':
   p=source/'collected/host-plan.json';data=r.read(p);data['provenance'].update(protocol_sha256='ff'*32,source_fingerprint='ee'*32)
   p.chmod(0o644);p.write_bytes(r.c.canonical(data)+b'\n')
   for entry in record['files']:
    if entry['path']=='host-plan.json':entry.update(size=p.stat().st_size,sha256=r.sha(p))
   for name,data in [('controller-receipt.json',record),('custody.json',r.c.custody_for(source/'collected',record))]:
    (source/name).unlink();r.c.write(source/name,data)
   # Byte transport positive prior to the independent-pin rejection.
   assert r.driver.check(source,allow_inner=True)['operational_status']=='complete'
  outer=root/'supervisor';outer.mkdir()
  r.c.write(root/'fixture-protocol.json',{'protocol_id':'EXP-FIXTURE'})
  def fixed_tree(repo,config,dest,sdk=None,supervisor_identity=None):
   shutil.copytree(source,dest)
   rec=r.read(dest/'controller-receipt.json');rec['supervisor_identity']=supervisor_identity
   (dest/'controller-receipt.json').unlink();r.c.write(dest/'controller-receipt.json',rec)
   return rec
  if label=='zero-start-envelope':
   def no_engine(*args,**kwargs):raise ValueError('fixed source refusal before engine start')
   run=fixed_tree
   with patch.object(r.c,'run',side_effect=no_engine):
    r.driver.run(root,{'inputs':{'protocol':{'path':'fixture-protocol.json'}}},outer,experiment_id='EXP-FIXTURE',run_id='RUN-FIXTURE')
  else:
   with patch.object(r.c,'run',side_effect=fixed_tree):
    r.driver.run(root,{'inputs':{'protocol':{'path':'fixture-protocol.json'}}},outer,experiment_id='EXP-FIXTURE',run_id='RUN-FIXTURE')
  integrity=r.driver.check(outer)
  if label=='positive-envelope':
   assert integrity['operational_status']=='complete'
   answers[label]={'driver_check':integrity,'files':{n:r.sha(outer/n) for n in ['manifest.yaml','raw-result.json','modal-evidence.tar.gz','modal-evidence-manifest.json']}}
   continue
  if label=='corrupt-archive':(outer/'modal-evidence.tar.gz').write_bytes(b'REVIEWER-CORRUPT-ARCHIVE')
  if label=='missing-member':(outer/'modal/collected/raw/traces.jsonl').unlink()
  reached={'verify':0,'reference':0,'entropy':0,'renderer':0}
  realmodule=r.c.module
  def guarded_module(path,name):
   if name in ['verify','reference']:
    reached[name]+=1;raise AssertionError('host module reached')
   if name=='_controlled_render':
    reached['renderer']+=1;return types.SimpleNamespace(render=lambda dest:None)
   return realmodule(path,name)
  def entropy(*args):reached['entropy']+=1;raise AssertionError('host entropy reached')
  with patch.object(r.c,'make_plan',return_value=(expected,invocation,{},{})),patch.object(r.c,'module',side_effect=guarded_module),patch.object(r.post.os,'urandom',side_effect=entropy):
   result=r.post.run(outer,root/'postrun',r.REPO)
  assert result['status']=='incomplete'
  assert reached['verify']==reached['reference']==reached['entropy']==0
  message=result['errors'][0]['message']
  want={'corrupt-archive':'evidence archive hashes','missing-member':'unbound or missing supervisor tree member','wrong-independent-pins':'independent invocation','zero-start-envelope':'operational failure'}[label]
  assert want in message,(label,message)
  answers[label]={'pre_mutation_driver_check':integrity,'result':result,'guard_calls':reached,'report_render_suppressed':True}
 return {'cases':answers,'provider_boundary':'c.run replaced by retained fixed F11 tree copy; no SDK object imported/called','outer_supervisor':'real driver.run/seal_evidence/check; synthetic IDs EXP-FIXTURE/RUN-FIXTURE','wrong_pin_seam':'ordinary postrun branch with only c.make_plan frozen expected tuple injected; no verifier/fixture_law injection','clock_vm_os_qualification':False}

def authenticate_sources():
 root=r.WORK/'cases/actual-source-authentication';shutil.copytree(HIST,root)
 roles=['protocol','image_receipt','engine_plan','prior_exclusions','worker_manifest','host_manifest','engine_interface','host_interface']
 for role in ['worker_manifest','host_manifest']:
  shutil.copy2(r.REPO/r.PREFIX/(role.replace('_','-').replace('manifest','source-manifest')+'.json'),root/(role+'.json'))
 for role in ['image_receipt','engine_plan','prior_exclusions','host_interface']:r.write(root/(role+'.json'),{})
 static={role:r.read(root/(role+'.json')) for role in roles}
 invocation={'inputs':{role:{'sha256':r.sha(root/(role+'.json')),'path':role+'.json'} for role in roles}}
 wm=static['worker_manifest'];hm=static['host_manifest'];finger=r.c.sha_bytes(r.c.canonical({'worker':wm,'host':hm}))
 record=r.read(root/'controller-receipt.json');record['plan']['source_fingerprint']=finger
 worker={'provenance':{'protocol_sha256':invocation['inputs']['protocol']['sha256'],'source_fingerprint':finger}}
 with patch.object(r.c,'make_plan',return_value=(record['plan'],invocation,static,{})):
  positive=r.post.authenticate_inputs(root,r.REPO,record,worker)
 assert positive['workload_law']=='production/v1'
 mutants={}
 for role in roles:
  p=root/(role+'.json');data=p.read_bytes();p.chmod(0o644);p.write_bytes(data+b' ')
  try:
   with patch.object(r.c,'make_plan',return_value=(record['plan'],invocation,static,{})):
    r.post.authenticate_inputs(root,r.REPO,record,worker)
   raise AssertionError('copied input accepted '+role)
  except ValueError as error:
   assert 'copied input hash mismatch: '+role in str(error);mutants[role]=str(error)
  finally:p.write_bytes(data)
 return {'positive':positive,'source_fingerprint':finger,'worker_files':wm['files'],'host_files':hm['files'],'copied_role_mutants':mutants,'independent_plan_builder':'c.make_plan injected; actual source_payload and executing-module byte checks run','actual_sdk_called':False}

def preflight_cell_guards():
 # Exercise unchanged pre-oracle stream/identity check with a supplied minimal
 # schedule; fixed paired records never impersonate the production population.
 host=r.c.module(r.REPO/r.PREFIX/'host/verify.py','review_host_preflight')
 traces=r.rows(r.FIX/'paired/collected/raw/traces.jsonl')[:2]
 cells=r.rows(r.FIX/'paired/collected/raw/decoder-cells.jsonl')
 # Metadata/arm validity is not the subject of this seam. The unchanged record
 # schema checker is used for cells and the direct stream guard for identities.
 interface=r.read(r.REPO/r.PREFIX/'engine-interface.json')
 import jsonschema
 schemas=interface['record_schemas'] if 'record_schemas' in interface else None
 schedule={'setup_ids':{},'single_ids':{},'trace_ids':{},'paired_trace_ids':{t['trace_id']:{} for t in traces},'expected':{'cells':12}}
 answers={}
 for label in ['complete-cells','duplicate-cell-id','missing-cell','padded-cell-id']:
  cc=copy.deepcopy(cells)
  if label=='duplicate-cell-id':cc[-1]=copy.deepcopy(cc[0])
  if label=='missing-cell':cc.pop()
  if label=='padded-cell-id':cc.append(copy.deepcopy(cc[0]));cc[-1]['cell_id']='fake-extra-cell'
  def records(seal,name):return iter(cc if name=='decoder-cells.jsonl' else [])
  try:
   with patch.object(host,'iter_records',side_effect=records):host.preflight_records(None,schedule,lambda *args:None)
   message=None
  except ValueError as error:message=str(error)
  if label=='complete-cells':assert message is None
  else:assert message and ('cell ID' in message or 'complete cell schedule' in message)
  answers[label]={'error':message}
 return {'cases':answers,'seam':'iter_records and record schema check supplied directly; unchanged cell identity/count code; no Oracle constructed; not full verify_bundle production invocation'}

def ancestry():
 commits=['c4d0d3ed9d0732a72559a11871271e195635af88','a7b60afdf7b15dceb59d38fd301c05f73deef425','c417f00dff28e811873dbf9e8f44d4b99df4533f','416dea22ea3a0b8accb50c10beef2f379ce5725b','0047c968f61c796ca27cd9e0b528cfe9d92f7284','b88c661b100d793c43e9099e03beee3567cf2344','8de1c30e9d','2fda1d318f']
 for i,commit in enumerate(commits):
  r.command('commit-files-'+commit[:10],['git','show','--format=fuller','--stat','--oneline',commit])
  if i:r.command('ancestor-'+commits[i-1][:10]+'-'+commit[:10],['git','merge-base','--is-ancestor',commits[i-1],commit])
  r.command('pushed-ref-'+commit[:10],['git','for-each-ref','--contains='+commit,'--format=%(refname)','refs/remotes/origin/'])
 receipt=r.read(r.REPO/r.BATCH/'archives/TASK-20261029-b5a89f/snapshot-receipt.json')
 commit=receipt['archive_binding']['commit_sha'];bound={}
 for path,digest in receipt['archive_binding']['path_sha256'].items():
  run=r.command('snapshot-bytes-'+Path(path).name,['git','show',commit+':'+path])
  h=hashlib.sha256(run.stdout.encode()).hexdigest();assert h==digest==r.sha(r.REPO/path)
  bound[path]=h
 # Hash byte reads are repeated with check_output rather than text for manifests.
 manifests={}
 for kind in ['worker','host']:
  m,payload=r.c.source_payload(r.REPO,r.REPO/r.PREFIX/(kind+'-source-manifest.json'),kind)
  manifests[kind]={'count':len(payload),'files':{p:hashlib.sha256(data).hexdigest() for p,data in payload.items()},'source_revision':m['source_revision']}
 assert len(manifests['worker']['files'])==5 and len(manifests['host']['files'])==13
 return {'order':commits,'snapshot_content_map':bound,'actual_full_manifests':manifests,'git_mutations':False}

def main():
 r.case('full_freeze',full_freeze)
 r.case('lifecycle',lifecycle)
 r.case('authenticate_sources',authenticate_sources)
